import {ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';

// Counting executors, since input validation is judged by whether the executor is reached at all.
const countingExecutor =
  (into: Array<Record<string, unknown>>, answer: string) =>
  async (input: Record<string, unknown>): Promise<string> => {
    into.push(input);
    return answer;
  };

describe('ToolRegistry inputSchema validation', () => {
  it('rejects input missing a required property and does not call the executor', async () => {
    const registry = new ToolRegistry();
    let calls = 0;
    registry.register(
      {
        name: 'weather_lookup',
        description: 'Look up current weather',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        calls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('weather_lookup', {});

    expect({calls, namesLocation: /location/.test(response.result), namesRequired: /required/i.test(response.result)}).toEqual({
      calls: 0,
      namesLocation: true,
      namesRequired: true,
    });
  });

  it('rejects a wrong-typed value naming the field path and expected type without echoing the value', async () => {
    const registry = new ToolRegistry();
    const executed: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'record_search',
        description: 'Search records by query text',
        inputSchema: {
          type: 'object',
          properties: {query: {type: 'string'}},
          required: ['query'],
        },
      },
      countingExecutor(executed, 'found')
    );

    const response = await registry.execute('record_search', {query: 8675309});
    const result = response.result;

    expect({
      executed,
      namesField: result.includes('query'),
      namesType: result.includes('string'),
      echoesValue: result.includes('8675309'),
    }).toEqual({executed: [], namesField: true, namesType: true, echoesValue: false});
  });

  it('passes undeclared extra properties through to the executor unchanged and exactly once', async () => {
    const registry = new ToolRegistry();
    const executed: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'note_creator',
        description: 'Create a note',
        inputSchema: {
          type: 'object',
          properties: {title: {type: 'string'}},
          required: ['title'],
        },
      },
      countingExecutor(executed, 'ok')
    );
    const input = {title: 'groceries', tagged: true, extra: 'kept'};

    await registry.execute('note_creator', input);

    expect(executed).toEqual([input]);
  });

  it('throws Unknown tool for an unregistered name', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('never_registered', {})).rejects.toThrow('Unknown tool: never_registered');
  });

  it('keeps enforcing the schema a static tool was registered with across repeated execute calls', async () => {
    const registry = new ToolRegistry();
    const executed: Array<Record<string, unknown>> = [];
    const definition: ToolDefinition = {
      name: 'city_lookup',
      description: 'Look up a city',
      inputSchema: {
        type: 'object',
        properties: {city: {type: 'string'}},
        required: ['city'],
      },
    };
    registry.register(definition, countingExecutor(executed, 'ok'));
    // Validation must keep using the validator compiled at register time, not re-read the definition.
    definition.inputSchema = {type: 'object'};

    const results: string[] = [];
    for (let call = 0; call < 10; call++) {
      results.push((await registry.execute('city_lookup', {})).result);
    }

    expect({allRejectedForCity: results.every(result => /city/.test(result)), executed}).toEqual({
      allRejectedForCity: true,
      executed: [],
    });
  });

  it('validates a function-valued source against the schema it returns for that call', async () => {
    const registry = new ToolRegistry();
    const executed: Array<Record<string, unknown>> = [];
    let requireCity = false;
    registry.register(
      () => ({
        name: 'place_finder',
        description: 'Find a place',
        inputSchema: requireCity
          ? {
              type: 'object',
              properties: {city: {type: 'string'}},
              required: ['city'],
            }
          : {
              type: 'object',
              properties: {region: {type: 'string'}},
              required: ['region'],
            },
      }),
      countingExecutor(executed, 'ok')
    );

    const acceptedBefore = await registry.execute('place_finder', {region: 'Brittany'});
    requireCity = true;
    const rejectedAfter = await registry.execute('place_finder', {region: 'Brittany'});
    const acceptedAfter = await registry.execute('place_finder', {city: 'Brest'});

    expect({
      executed,
      acceptedBefore: acceptedBefore.result,
      rejectedForCity: /city/.test(rejectedAfter.result),
      acceptedAfter: acceptedAfter.result,
    }).toEqual({
      executed: [{region: 'Brittany'}, {city: 'Brest'}],
      acceptedBefore: 'ok',
      rejectedForCity: true,
      acceptedAfter: 'ok',
    });
  });

  it('exposes a registered tool through get and reports nothing for an unknown name', () => {
    const registry = new ToolRegistry();
    const executor = async (): Promise<string> => 'ok';
    registry.register(
      {
        name: 'invoice_fetch',
        description: 'Fetch an invoice by id',
        inputSchema: {type: 'object', properties: {id: {type: 'string'}}, required: ['id']},
      },
      executor
    );
    const found = registry.get('invoice_fetch');

    expect({
      name: found?.definition.name ?? null,
      description: found?.definition.description ?? null,
      sameExecutor: found?.execute === executor,
      unknown: registry.get('never_registered') ?? null,
    }).toEqual({name: 'invoice_fetch', description: 'Fetch an invoice by id', sameExecutor: true, unknown: null});
  });

  it('collects prompt instructions and example prompts only from tools that declare them', () => {
    const registry = new ToolRegistry();
    const executor = async (): Promise<string> => 'ok';
    registry.register(
      {
        name: 'order_status',
        description: 'Report an order status',
        inputSchema: {type: 'object', properties: {order: {type: 'string'}}, required: ['order']},
        promptInstructions: 'Call when the user asks where an order is',
        examplePrompts: ['where is my order?'],
      },
      executor
    );
    registry.register(
      {name: 'opaque_tool', description: 'Declares neither field', inputSchema: {type: 'object'}},
      executor
    );

    expect({instructions: registry.getPromptInstructions(), examples: registry.getExamplePrompts()}).toEqual({
      instructions: ['order_status: Call when the user asks where an order is'],
      examples: ['where is my order?'],
    });
  });

  it('reports whether a name is registered through has', () => {
    const registry = new ToolRegistry();
    registry.register(
      {name: 'currency_convert', description: 'Convert an amount', inputSchema: {type: 'object'}},
      async () => 'ok'
    );

    expect({known: registry.has('currency_convert'), unknown: registry.has('never_registered')}).toEqual({
      known: true,
      unknown: false,
    });
  });
});

